def get_table_node(doc, scope):
    for node in scope_nodes(doc, scope):
        if node.get('kind') == 'table':
            return node
    return None

def entities(doc, scope):
    table_node = get_table_node(doc, scope)
    if not table_node:
        return []
    columns = table_node.get('columns', [])
    if not columns:
        return []
    ent_col = columns[0]
    seen = set()
    res = []
    for _, row_dict in table_rows(table_node):
        val = row_dict.get(ent_col, '').strip()
        if not val or val in ('—', '-', '–'):
            continue
        if re.search(r'\(.*in.*\)', val, re.I) or parse_year(val):
            continue
        if val.endswith(':'):
            continue
        if val not in seen:
            seen.add(val)
            res.append({"id": val, "description": val})
    return res

def recorded_end(doc, scope):
    table_node = get_table_node(doc, scope)
    if not table_node:
        return None
    years = []
    for col in table_node.get('columns', []):
        y = parse_year(col)
        if y:
            years.append(y)
    rows = table_rows(table_node)
    if rows:
        first_row = rows[0][1]
        for col in table_node.get('columns', []):
            y = parse_year(first_row.get(col, ''))
            if y:
                years.append(y)
    return float(max(years)) if years else None

